class Solution {
public:
    vector<int> singleNumber(vector<int>& nums) {
        long long xor_all = 0;
        for (int x : nums) xor_all ^= x;
        long long diff = xor_all & -xor_all;
        int a = 0, b = 0;
        for (int x : nums) {
            if (x & diff) a ^= x;
            else b ^= x;
        }
        return {a, b};
    }
};

class Solution {
    public int[] singleNumber(int[] nums) {
        int xorAll = 0;
        for (int x : nums) xorAll ^= x;
        int diff = xorAll & -xorAll;
        int a = 0, b = 0;
        for (int x : nums) {
            if ((x & diff) != 0) a ^= x;
            else b ^= x;
        }
        return new int[]{a, b};
    }
}

var singleNumber = function(nums) {
    let xorAll = 0;
    for (const x of nums) xorAll ^= x;
    const diff = xorAll & -xorAll;
    let a = 0, b = 0;
    for (const x of nums) {
        if (x & diff) a ^= x;
        else b ^= x;
    }
    return [a, b];
};
